('2026-09-29', '23:39:51', false, '今天真的社恐犯了，之前在QQ群随机组了一个四个人的小队，两男两女，今晚老师突然说搞什么小组作业让我们一个组坐一块，结果另一个女生没来，我就被迫和另外两个不认识的男生面基了…他俩一个坐我后面一个坐旁边，真的好尴尬', '邵慧留', '2026-09-29 23:39:51'),
('2026-09-29', '23:40:06', false, '等我仔细算算', '邵慧留', '2026-09-29 23:40:06'),
('2026-09-29', '23:41:58', false, '我也引用这句话，如果今天晚上课上坐我旁边的同学换成你，我一点都不会觉得不自在，相反很放松开心', '邵慧留', '2026-09-29 23:41:58'),
