('2026-09-30', '00:42:15', false, '本来目的地就偏僻哈哈', '邵慧留', '2026-09-30 00:42:15'),
('2026-09-30', '00:42:42', true, '[Chuckle]', '冬.暖凉', '2026-09-30 00:42:42'),
('2026-09-30', '00:43:29', true, '哎，话说你，确定你今天早上4点能从宿舍里出来吗？', '冬.暖凉', '2026-09-30 00:43:29'),
('2026-09-30', '00:43:39', true, '你确定宿管阿姨不会走，或者说去别的其他地方？', '冬.暖凉', '2026-09-30 00:43:39'),
('2026-09-30', '00:43:48', false, '这个问题我还得感谢你', '邵慧留', '2026-09-30 00:43:48'),
('2026-09-30', '00:44:11', true, '啥？所以你问了吗？', '冬.暖凉', '2026-09-30 00:44:11'),
('2026-09-30', '00:44:30', false, '刚下晚自习回到宿舍，不到二十分钟突然想起来没跟宿管阿姨说，又跑回一楼和她讲好', '邵慧留', '2026-09-30 00:44:30'),
('2026-09-30', '00:45:08', true, '哦？他们晚上是不是去别的地方睡觉去了？我有一次我晚上11点半我想出来，我都没找着他', '冬.暖凉', '2026-09-30 00:45:08'),
('2026-09-30', '00:45:19', false, '她说她给我留门，我出去后把门关上就行，不能让保安看出来门是明目张胆地开着的', '邵慧留', '2026-09-30 00:45:19'),
('2026-09-30', '00:45:55', true, '哦哦', '冬.暖凉', '2026-09-30 00:45:55'),
('2026-09-30', '00:46:01', true, '他人还怪好的嘞', '冬.暖凉', '2026-09-30 00:46:01'),
('2026-09-30', '00:46:43', false, '应该不是，我们宿舍楼的阿姨就睡一楼，可以敲她的门，但是会打扰到，所以阿姨想了个两全其美的办法', '邵慧留', '2026-09-30 00:46:43'),
('2026-09-30', '00:47:01', false, '[动画表情]', '邵慧留', '2026-09-30 00:47:01'),
('2026-09-30', '00:47:23', true, '哈哈哈哈', '冬.暖凉', '2026-09-30 00:47:23'),
('2026-09-30', '00:47:26', false, '这个，真的随时能出去吗', '邵慧留', '2026-09-30 00:47:26'),
('2026-09-30', '00:47:43', true, '啊，是啊，我自己开门就走呗，又没人拦着我', '冬.暖凉', '2026-09-30 00:47:43'),
('2026-09-30', '00:47:52', true, '所以说我担心的是你能不能走得了', '冬.暖凉', '2026-09-30 00:47:52'),
('2026-09-30', '00:48:07', true, '我以为你跟宿管阿姨约好时间了呢，所以说你说时间不合适', '冬.暖凉', '2026-09-30 00:48:07'),
('2026-09-30', '00:48:31', false, '你等一下', '邵慧留', '2026-09-30 00:48:31'),
('2026-09-30', '00:48:38', false, '这个问题怎么', '邵慧留', '2026-09-30 00:48:38'),
('2026-09-30', '00:48:57', false, '我说时间不合适是针对你问题本身', '邵慧留', '2026-09-30 00:48:57'),
('2026-09-30', '00:49:50', true, '怎么啦，我说什么了？我就是照着你问我的问题反问了一下，并且说了一下我的误会[Grimace]', '冬.暖凉', '2026-09-30 00:49:50'),
('2026-09-30', '00:50:52', false, '好吧就当咱俩逻辑思维不一样', '邵慧留', '2026-09-30 00:50:52'),
('2026-09-30', '00:51:40', true, '好吧，你是想说我的问题，本身“时间”不合适？', '冬.暖凉', '2026-09-30 00:51:40'),
('2026-09-30', '00:51:58', true, '我真是不太理解，这个问题为什么会有时间这个属性？', '冬.暖凉', '2026-09-30 00:51:58'),
('2026-09-30', '00:52:28', false, '你起的头喽', '邵慧留', '2026-09-30 00:52:28'),
('2026-09-30', '00:52:42', false, '时间一直都存在', '邵慧留', '2026-09-30 00:52:42'),
('2026-09-30', '00:52:49', false, '不能忽略', '邵慧留', '2026-09-30 00:52:49'),
('2026-09-30', '00:53:21', false, '嗯哼，跳过这个话题', '邵慧留', '2026-09-30 00:53:21'),
('2026-09-30', '00:53:28', false, '撤回了一条消息', '邵慧留', '2026-09-30 00:53:28'),
('2026-09-30', '00:53:45', false, '看到了～～～', '邵慧留', '2026-09-30 00:53:45'),
('2026-09-30', '00:53:53', false, '撤回不够快', '邵慧留', '2026-09-30 00:53:53'),
('2026-09-30', '00:54:04', true, '好的，不谈这个话题', '冬.暖凉', '2026-09-30 00:54:04'),
('2026-09-30', '00:54:27', false, '快一点了你真不睡：', '邵慧留', '2026-09-30 00:54:27'),
('2026-09-30', '00:54:50', false, '我突然又很想问一些', '邵慧留', '2026-09-30 00:54:50'),
('2026-09-30', '00:54:55', true, '不跟你说了嘛？今天不是平凡的一天', '冬.暖凉', '2026-09-30 00:54:55'),
('2026-09-30', '00:55:01', true, '什么呀？', '冬.暖凉', '2026-09-30 00:55:01'),
('2026-09-30', '00:55:23', false, '撤回了一条消息', '邵慧留', '2026-09-30 00:55:23'),
('2026-09-30', '00:55:57', true, '呃呃', '冬.暖凉', '2026-09-30 00:55:57'),
('2026-09-30', '00:56:22', false, '肖老师不想说我可以不问，突然好奇罢了', '邵慧留', '2026-09-30 00:56:22'),
('2026-09-30', '00:56:31', false, '[动画表情]', '邵慧留', '2026-09-30 00:56:31'),
('2026-09-30', '00:56:42', true, '没事，你既然都问了，其实也没什么', '冬.暖凉', '2026-09-30 00:56:42'),
('2026-09-30', '00:57:05', true, '其实我一直没有那种抑郁带来的失眠', '冬.暖凉', '2026-09-30 00:57:05'),
('2026-09-30', '00:57:24', false, '¿', '邵慧留', '2026-09-30 00:57:24'),
('2026-09-30', '00:57:37', true, '我一直都是那种躁狂期，带来的失眠，其实都不能算是失眠，而是睡眠的需求量减少，可能在一段时间内睡眠会缩短到三四个小时每天', '冬.暖凉', '2026-09-30 00:57:37'),
('2026-09-30', '00:58:00', true, '但是长此以往都会给身体带来巨大的负担，会导致头痛啊，思维迟钝，还有认知，记忆力下降等等', '冬.暖凉', '2026-09-30 00:58:00'),
('2026-09-30', '00:58:09', true, '就是这样，必须得干预', '冬.暖凉', '2026-09-30 00:58:09'),
('2026-09-30', '00:59:47', false, '隔着屏幕抱抱你', '邵慧留', '2026-09-30 00:59:47'),
('2026-09-30', '01:00:24', true, '抱抱', '冬.暖凉', '2026-09-30 01:00:24'),
('2026-09-30', '01:01:12', false, '其实今天真的有这个想法哈哈', '邵慧留', '2026-09-30 01:01:12'),
('2026-09-30', '01:01:26', false, '一种冲动', '邵慧留', '2026-09-30 01:01:26'),
('2026-09-30', '01:01:38', true, '在现实中？', '冬.暖凉', '2026-09-30 01:01:38'),
('2026-09-30', '01:01:52', false, '嗯', '邵慧留', '2026-09-30 01:01:52'),
('2026-09-30', '01:02:12', false, '我拿了你送我的画，往松2宿舍楼走的时候', '邵慧留', '2026-09-30 01:02:12'),
('2026-09-30', '01:02:24', false, '你往桃去，我一直回头看你', '邵慧留', '2026-09-30 01:02:24'),
('2026-09-30', '01:02:37', true, '那不瞒着你说了', '冬.暖凉', '2026-09-30 01:02:37'),
('2026-09-30', '01:02:53', false, '但是不敢付诸行动', '邵慧留', '2026-09-30 01:02:53'),
('2026-09-30', '01:03:12', true, '其实我也有这种想法，我觉得如果那真是最后的道别的话，也许可以正式一点，我记得和你分别的时候，你往前走了几步台阶，我往后瞅了一眼，但是我发现你很决绝，我便放弃了这种想法', '冬.暖凉', '2026-09-30 01:03:12'),
('2026-09-30', '01:03:24', true, '没想到是一种，完美的错过', '冬.暖凉', '2026-09-30 01:03:24'),
('2026-09-30', '01:03:50', false, '哈哈咱俩跟拍偶像剧似的', '邵慧留', '2026-09-30 01:03:50'),
('2026-09-30', '01:03:57', false, '有点好笑', '邵慧留', '2026-09-30 01:03:57'),
('2026-09-30', '01:04:11', true, '哈哈哈', '冬.暖凉', '2026-09-30 01:04:11'),
('2026-09-30', '01:04:34', true, '没想到现实中其实比偶像剧更精彩，是吧？因为自己成了主角', '冬.暖凉', '2026-09-30 01:04:34'),
('2026-09-30', '01:05:08', false, '这句话我很认同，如果真的是最后的告别，应该更正式', '邵慧留', '2026-09-30 01:05:08'),
('2026-09-30', '01:05:40', true, '哈哈，其实我当时是调整了一下想法的，我看了一下你的状态，好像跟平时看不出来任何不同', '冬.暖凉', '2026-09-30 01:05:40'),
('2026-09-30', '01:05:51', true, '我觉得可能在你的眼中，这就是一个再平常不过的分别了吧，毕竟之后也许可以再见面', '冬.暖凉', '2026-09-30 01:05:51'),
('2026-09-30', '01:06:11', true, '然后我就调整了一下想法，就说服自己认为他是一个平常的分别吧', '冬.暖凉', '2026-09-30 01:06:11'),
('2026-09-30', '01:06:43', false, '离别是人生的常态', '邵慧留', '2026-09-30 01:06:43'),
('2026-09-30', '01:06:51', false, '哈哈突然高大上', '邵慧留', '2026-09-30 01:06:51'),
('2026-09-30', '01:07:09', true, '嘿嘿，早日重逢', '冬.暖凉', '2026-09-30 01:07:09'),
('2026-09-30', '01:07:25', false, '咱俩应该没到，缘分未尽', '邵慧留', '2026-09-30 01:07:25'),
('2026-09-30', '01:07:44', true, '希望', '冬.暖凉', '2026-09-30 01:07:44'),
('2026-09-30', '01:08:14', false, '撤回了一条消息', '邵慧留', '2026-09-30 01:08:14'),
('2026-09-30', '01:08:25', false, '肖弋洋国庆有什么计划', '邵慧留', '2026-09-30 01:08:25'),
('2026-09-30', '01:08:33', false, '七天假期呢', '邵慧留', '2026-09-30 01:08:33'),
('2026-09-30', '01:08:48', false, '撤回了一条消息', '邵慧留', '2026-09-30 01:08:48'),
('2026-09-30', '01:09:01', true, '嘿嘿，跟你学的', '冬.暖凉', '2026-09-30 01:09:01'),
('2026-09-30', '01:09:04', false, '（笑）', '邵慧留', '2026-09-30 01:09:04'),
('2026-09-30', '01:09:24', true, '我觉得不出什么意外的话，应该是敲敲代码学学习吧', '冬.暖凉', '2026-09-30 01:09:24'),
('2026-09-30', '01:09:47', false, '努力又上进的肖老师', '邵慧留', '2026-09-30 01:09:47'),
('2026-09-30', '01:09:48', false, '或者说', '邵慧留', '2026-09-30 01:09:48'),
('2026-09-30', '01:09:59', false, '这才是你的日常？', '邵慧留', '2026-09-30 01:09:59'),
('2026-09-30', '01:10:06', false, '一直都很认真', '邵慧留', '2026-09-30 01:10:06'),
('2026-09-30', '01:10:07', true, '你也是我的日常', '冬.暖凉', '2026-09-30 01:10:07'),
('2026-09-30', '01:10:15', true, '我也很认真', '冬.暖凉', '2026-09-30 01:10:15'),
('2026-09-30', '01:10:38', true, '没有  才', '冬.暖凉', '2026-09-30 01:10:38'),
('2026-09-30', '01:11:16', false, '其实咱俩相处“才”算意外', '邵慧留', '2026-09-30 01:11:16'),
('2026-09-30', '01:11:53', false, '本来轨道是既定的', '邵慧留', '2026-09-30 01:11:53'),
('2026-09-30', '01:12:04', false, '出现了偏差', '邵慧留', '2026-09-30 01:12:04'),
('2026-09-30', '01:12:33', true, '有没有可能这个偏差本身也是既定的？也是这个诡道的一部分', '冬.暖凉', '2026-09-30 01:12:33'),
('2026-09-30', '01:14:06', false, '好像在遇见你之前，这种可能都不存在，跟你相处完全在我的意料之外', '邵慧留', '2026-09-30 01:14:06'),
('2026-09-30', '01:14:26', false, '我本来觉得一个人挺好的', '邵慧留', '2026-09-30 01:14:26'),
('2026-09-30', '01:15:09', false, '但是跟你这么优秀的人接触后，开始有点被这种情绪带着走了', '邵慧留', '2026-09-30 01:15:09'),
('2026-09-30', '01:15:28', false, '就是我之前说的“一股脑”', '邵慧留', '2026-09-30 01:15:28'),
('2026-09-30', '01:16:23', true, '其实在遇到你之前，我的生活也遇到了很大的困境', '冬.暖凉', '2026-09-30 01:16:23'),
('2026-09-30', '01:16:47', true, '但很难想象这种困境仅仅是因为遇到了你，就在几十个小时之内被逆转了', '冬.暖凉', '2026-09-30 01:16:47'),
('2026-09-30', '01:18:11', false, '嗯，所以现在这样蛮好的，不用想太多，就简简单单能笑一笑都是赚了的感觉哈哈', '邵慧留', '2026-09-30 01:18:11'),
('2026-09-30', '01:18:25', false, '我以前总是会纠结', '邵慧留', '2026-09-30 01:18:25'),
('2026-09-30', '01:18:54', false, '撤回了一条消息', '邵慧留', '2026-09-30 01:18:54'),
('2026-09-30', '01:19:41', false, '撤回了一条消息', '邵慧留', '2026-09-30 01:19:41'),
('2026-09-30', '01:19:51', true, '哈哈，是的，享受和你在一起的每1秒', '冬.暖凉', '2026-09-30 01:19:51'),
('2026-09-30', '01:20:13', false, '有点胡言乱语了哈哈', '邵慧留', '2026-09-30 01:20:13'),
('2026-09-30', '01:20:19', true, '嘶~', '冬.暖凉', '2026-09-30 01:20:19'),
('2026-09-30', '01:20:29', false, '可能现在太晚了', '邵慧留', '2026-09-30 01:20:29'),
('2026-09-30', '01:20:47', false, '夜深人静', '邵慧留', '2026-09-30 01:20:47'),
('2026-09-30', '01:20:52', true, '不过你那两句话的确看起来很令人难以理解', '冬.暖凉', '2026-09-30 01:20:52'),
('2026-09-30', '01:21:19', false, '哈哈你其实可以当做没看到', '邵慧留', '2026-09-30 01:21:19'),
('2026-09-30', '01:21:22', false, '[动画表情]', '邵慧留', '2026-09-30 01:21:22'),
('2026-09-30', '01:21:26', true, '哈哈，其实我也没看懂', '冬.暖凉', '2026-09-30 01:21:26'),
('2026-09-30', '01:22:19', false, '肖老师愿意再跟我说一些别的事儿吗？', '邵慧留', '2026-09-30 01:22:19'),
('2026-09-30', '01:22:42', true, '我吗？', '冬.暖凉', '2026-09-30 01:22:42'),
('2026-09-30', '01:22:53', true, '你是想听我什么方面的事儿？', '冬.暖凉', '2026-09-30 01:22:53'),
('2026-09-30', '01:23:10', false, '你之前说住了三次院？为什么是三次', '邵慧留', '2026-09-30 01:23:10'),
('2026-09-30', '01:23:40', true, '因为病情不断恶化了三次，可以说', '冬.暖凉', '2026-09-30 01:23:40'),
('2026-09-30', '01:24:00', true, '哎呀，不过我补充一下，虽然，我说这些比较悲伤的事情，但是我觉得你还是不要太可怜或者同情我', '冬.暖凉', '2026-09-30 01:24:00'),
('2026-09-30', '01:24:06', false, '每一次出院不是代表着病情在好转吗？', '邵慧留', '2026-09-30 01:24:06'),
('2026-09-30', '01:24:27', false, '没有同情或者可怜，只有心疼', '邵慧留', '2026-09-30 01:24:27'),
('2026-09-30', '01:24:45', false, '想多了解你一点', '邵慧留', '2026-09-30 01:24:45'),
('2026-09-30', '01:25:15', true, '其实我不是不愿意跟你讲这些事情，跟你讲这些事情其实没什么影响，主要是这可能让你错误的认识我这个人，可能有的时候你会受到主观上的一些影响，就比如说你说的心疼，然后可能你看到的就不是我这个客观的人了', '冬.暖凉', '2026-09-30 01:25:15'),
('2026-09-30', '01:25:58', false, '人都是多面的，我觉得认识不同的你没毛病', '邵慧留', '2026-09-30 01:25:58'),
('2026-09-30', '01:26:23', false, '其实很多时候没有绝对客观', '邵慧留', '2026-09-30 01:26:23'),
('2026-09-30', '01:27:06', false, '或者说会产生各种情感才是正常的', '邵慧留', '2026-09-30 01:27:06'),
('2026-09-30', '01:27:32', false, '但是我也没有揭你伤口的意思对不起', '邵慧留', '2026-09-30 01:27:32'),
('2026-09-30', '01:27:47', true, '没有没有没有，我当然可以说', '冬.暖凉', '2026-09-30 01:27:47'),
('2026-09-30', '01:28:14', true, '其实有的时候出院并不代表好转，有的时候是有一些无奈的一种选择，或者是一些被逼无奈的决定', '冬.暖凉', '2026-09-30 01:28:14'),
('2026-09-30', '01:28:52', false, '我好像不是很懂', '邵慧留', '2026-09-30 01:28:52'),
('2026-09-30', '01:29:21', false, '住院是因为生病，病好了就出院，不对吗？病没好就继续住院', '邵慧留', '2026-09-30 01:29:21'),
('2026-09-30', '01:29:40', true, '就比如说有的时候我可能会选择出院，从而去接受一个更好的一个治疗，然后呢我可能，又出院一次，这次虽然说我住的医院还不错，但是可能我需要去再次尝试去上学，也就是我上次读大二的时候，但是很可惜他失败了，所以说我又得住院了，这次住院出院的原因也不是因为病好了，是因为我在医院里被关了三个半月，我实在是受不了了，我只能是选择伪装，装成一个正常人，然后出院', '冬.暖凉', '2026-09-30 01:29:40'),
('2026-09-30', '01:30:42', false, '伪装', '邵慧留', '2026-09-30 01:30:42'),
