('2026-09-30', '03:06:59', false, '哈哈哈', '邵慧留', '2026-09-30 03:06:59'),
('2026-09-30', '03:07:18', false, '我开始好奇你高中到底什么样子', '邵慧留', '2026-09-30 03:07:18'),
('2026-09-30', '03:07:23', true, '嗯？', '冬.暖凉', '2026-09-30 03:07:23'),
('2026-09-30', '03:07:28', false, '之前说过一些', '邵慧留', '2026-09-30 03:07:28'),
('2026-09-30', '03:07:38', false, '好像和现在差别有点大', '邵慧留', '2026-09-30 03:07:38'),
('2026-09-30', '03:07:54', true, '阿巴阿巴，就是学习啦，还有跟好朋友在学校里转圈圈，没事的时候', '冬.暖凉', '2026-09-30 03:07:54'),
