('2026-09-30', '12:35:43', true, '【案例分析】
      9月8日，某学生在小红书里看到网名“小红薯6AA2AA48”发帖，称投资股票收益赚钱。于是联系对方，后被拉入群聊。群内陌生人私信，称小红书上聊炒股容易被禁言封号，指示该学生下载“雅言慧读”APP聊天。对方自称“中国银河证券公司拉升主力”，能买到涨停赚钱的股票。该学生抱着试一下的心态，点击链接下载“YH天王星”APP，登陆注册账号并实名认证。9月10日，该学生向“YH天王星”账户充值4930元买入推荐的股票，9月11日卖出，获得收益。后从9月11日至9月21日，该学生每日按照对方引导，买入卖出指定股票。为了验证真假，该学生提现11000余元到银行卡。9月23日，对方诱导申购新股，称新股能翻倍利润高，注资10万元入门金。该学生没钱，只能凑够4万元，对方称可以帮助在公司申请救助注资，随后发送一个链接。该学生点击链接，进入对方提供的账户，输入银行卡号、密码等申请救助。后学生银行卡自动扣款39433元，此时“YH天王星”账户显示认购新股成功。10分钟后，对方称还需要注资补齐之前差的6万多元，如果不继续注资将无法提现。该学生一听还要继续转钱，意识到被诈骗，报警求助。
【警方提示】
       所有“主动带你赚钱”的，全是骗子。正规投资行业没有“免费带单、专人荐股、稳赚不赔”一说。股市有风险、投资无捷径，陌生人主动私信、短视频引流、直播间带赚，一律是杀猪盘。天上不会掉馅饼，所有超出常理的高收益，背后都是精心布置的陷阱。', '冬.暖凉', '2026-09-30 12:35:43'),
('2026-09-30', '12:35:44', true, '【案例分析】
    9月21日18时许，某学生手机刷微博时，看到一博主的一条动态，下面评论里有粉丝进入群聊参加抽奖活动，于是加入群聊。进入后，群主在群里公布中奖名单，共有四名中奖者，该学生刚好是第三名。四个人要依次完成操作认证才能拿到奖品。后该学生收到私信，称前两个都已经完成了认证，并提供二维码让学生扫码联系客服，完成认证。扫码后，系统直接跳转至陌生网页，里面客服联系核对信息，并发送教学视频。该学生按照视频教程操作，扫码转账305元，但与视频教程不一致。联系客服，客服称操作失误，发送二维码让联系公司财务。该学生添加“财务人员”支付宝好友，与对方视频通话，后在“财务人员”的一番忽悠下，使用中国银行APP向对方提供的境外账户（FPP0 0000 ****28）转账3笔共8580元。
【警方提示】
      不要轻信所谓的“天降大奖”以及“押金换礼品”等骗术，牢记天上不会掉馅饼，保持警惕性。不要随意透露您的个人信息，包括身份证号、银行卡号、密码等敏感信息。收到对方提供的境外卡号，务必要再三核实，不要直接转，要向银行客服核实该账户是否合规。', '冬.暖凉', '2026-09-30 12:35:44'),
