('2026-09-30', '21:59:03', false, '¿', '邵慧留', '2026-09-30 21:59:03'),
('2026-09-30', '21:59:17', true, '就是被医生电失忆了，差不多', '冬.暖凉', '2026-09-30 21:59:17'),
('2026-09-30', '21:59:30', true, '美其名曰 无抽搐电休克（MECT）', '冬.暖凉', '2026-09-30 21:59:30'),
('2026-09-30', '22:00:14', true, '导致我对那段记忆还有以前的一些记忆,很模糊', '冬.暖凉', '2026-09-30 22:00:14'),
('2026-09-30', '22:07:26', true, '这么早呀？', '冬.暖凉', '2026-09-30 22:07:26'),
('2026-09-30', '22:11:21', false, '这种时候我真的很难过咱俩见不到面，刚刚特别想抱抱你安慰你，可能你不需要，因为所有的经历真实的痛苦，都是已经发生的过去的事，而且只有你自己真的懂，我感觉说任何安慰的话都显得特别苍白无力，但是我又特别不希望你难过，就刚刚看到那个MECT那时候真的心里一下揪了起来，我一直以为嗯，治疗的手段应该是相对比较温柔的，但是我把问题想的太简单了，而且我不能把你的痛苦美化，所以一直在想怎么能让你更开心一点', '邵慧留', '2026-09-30 22:11:21'),
('2026-09-30', '22:12:37', true, '不行不行不行，我其实就想调侃一下的，没那个意思，你不要同情我呀', '冬.暖凉', '2026-09-30 22:12:37'),
('2026-09-30', '22:12:49', true, '好叭，其实也没什么，已经过去了', '冬.暖凉', '2026-09-30 22:12:49'),
('2026-09-30', '22:13:56', false, '其实是因为要早起做一件事，可能到八九点的时候又可以睡个回笼觉了', '邵慧留', '2026-09-30 22:13:56'),
('2026-09-30', '22:15:14', true, '其实你不用一直想该怎么安慰我，也不用想着一定要让我开心一点。那些事情确实已经过去了，我现在跟你说这些也不是因为我还陷在里面，只是聊天刚好聊到了

不过你刚刚说特别想抱抱我的时候，我还是挺开心的哈哈。其实你愿意听我说这些，也愿意这么关心我，对我来说就已经够了

等回来再抱吧哈哈', '冬.暖凉', '2026-09-30 22:15:14'),
('2026-09-30', '22:16:16', false, '我突然想到了一个问题', '邵慧留', '2026-09-30 22:16:16'),
('2026-09-30', '22:16:23', false, '咱俩之间有社交距离吗？', '邵慧留', '2026-09-30 22:16:23'),
('2026-09-30', '22:16:38', false, '不对，好像我俩一般讲话都离得比较近', '邵慧留', '2026-09-30 22:16:38'),
('2026-09-30', '22:17:13', true, '哈哈哈你这么一说我才发现，好像确实没有什么社交距离，咱俩讲话的时候基本都离得挺近的', '冬.暖凉', '2026-09-30 22:17:13'),
('2026-09-30', '22:17:20', false, '正常社交距离应该要隔个一米哈哈', '邵慧留', '2026-09-30 22:17:20'),
('2026-09-30', '22:17:50', true, '那咱俩好像确实从来没遵守过这个标准哈哈哈', '冬.暖凉', '2026-09-30 22:17:50'),
('2026-09-30', '22:18:02', false, '之前都没注意，好像一点也不排斥跟你靠近', '邵慧留', '2026-09-30 22:18:02'),
('2026-09-30', '22:18:35', true, '我好像也是，之前完全没注意这个问题，就感觉跟你靠近挺自然的', '冬.暖凉', '2026-09-30 22:18:35'),
('2026-09-30', '22:18:48', true, '甚至还有一些享受', '冬.暖凉', '2026-09-30 22:18:48'),
('2026-09-30', '22:19:06', false, '哎，说起这个问题，如果是一般陌生的人靠近我，别人凑近我就后退，不喜欢陌生人离我太近，但是朋友之间就非常享受贴贴', '邵慧留', '2026-09-30 22:19:06'),
('2026-09-30', '22:19:17', false, '哈哈', '邵慧留', '2026-09-30 22:19:17'),
('2026-09-30', '22:19:44', true, '哦豁，那我好像明白了，你不是单纯不在意社交距离，是熟了之后反而挺喜欢这种身体上的亲近', '冬.暖凉', '2026-09-30 22:19:44'),
('2026-09-30', '22:20:18', false, '昂，我觉得肢体接触有时候特别舒服', '邵慧留', '2026-09-30 22:20:18'),
('2026-09-30', '22:20:44', false, '之前我跟你说，好像有一句', '邵慧留', '2026-09-30 22:20:44'),
('2026-09-30', '22:20:48', true, '确实哈哈哈，我感觉我也是，而且跟喜欢亲近的人靠在一起确实会很舒服', '冬.暖凉', '2026-09-30 22:20:48'),
('2026-09-30', '22:22:36', false, '当时体育课的时候，老师为了让我们舒展身体，让我们跟自己身边的同性做各种拉伸拥抱肩靠肩还有下腰的动作，有些动作确实有点姿势暧昧了哈哈', '邵慧留', '2026-09-30 22:22:36'),
('2026-09-30', '22:23:55', false, '我突然想起来，我高中的时候有时候和朋友开玩笑，把手搭在人家肩上，我俩就调侃，这个姿势做的很不舒服，因为我们没有身高差，一般个子高的把手搭在小个子的肩上就会很自然', '邵慧留', '2026-09-30 22:23:55'),
('2026-09-30', '22:24:47', true, '你们体育课还有这种项目吗，各种抱肩靠肩下腰，听起来确实有些动作会很奇怪', '冬.暖凉', '2026-09-30 22:24:47'),
('2026-09-30', '22:25:00', true, '哈不过你这么一说我才发现，搭肩这个动作好像确实特别吃身高差，差不多高的话手搭上去反而得歪着，不舒服哈', '冬.暖凉', '2026-09-30 22:25:00'),
('2026-09-30', '22:25:11', false, '哈哈哈', '邵慧留', '2026-09-30 22:25:11'),
('2026-09-30', '22:25:59', false, '[动画表情]', '邵慧留', '2026-09-30 22:25:59'),
('2026-09-30', '22:26:06', false, '[动画表情]', '邵慧留', '2026-09-30 22:26:06'),
