('2026-09-30', '23:06:47', false, '你生病的时候会有食欲不振的情况吗，就是不太想吃东西，还是特别想吃东西？', '邵慧留', '2026-09-30 23:06:47'),
('2026-09-30', '23:07:30', false, '我每次身体不舒服的时候就会想到“能吃是福”四个字，因为真的感觉就是通过食物摄入能量，才能抵抗那些不良反应', '邵慧留', '2026-09-30 23:07:30'),
('2026-09-30', '23:08:14', true, '有些药比如说富马酸，喹硫平，丙戊酸镁，还有一些抗精神病药，它会深刻的改变身体的代谢，会导致身体更倾向于留住糖分，把糖分转化成脂肪，而不是反过来去消耗它，再加上会导致食欲增加等等副作用，有的时候吃药会变胖', '冬.暖凉', '2026-09-30 23:08:14'),
('2026-09-30', '23:08:58', true, '幸亏我当时用了非常极端的饮食，就是每顿饭只吃大概两三勺饭吧，差不多就这个样子，然后没有胖太多', '冬.暖凉', '2026-09-30 23:08:58'),
