('2026-09-30', '23:11:04', true, '反正你已经这么瘦了', '冬.暖凉', '2026-09-30 23:11:04'),
('2026-09-30', '23:11:45', true, '我再补一句哈，你什么时候看我不吱声了，有可能是我手机又砸脸了', '冬.暖凉', '2026-09-30 23:11:45'),
('2026-09-30', '23:12:14', false, '啊啊，现在变成肖老师变得敏感了，我真的没想那么多，你不是说以后这些就只是咱俩话题中的一部分 只是聊天刚好聊到了，咱都先别说，其实我真的只是饿了哈哈', '邵慧留', '2026-09-30 23:12:14'),
('2026-09-30', '23:12:32', false, '你能不能拿好了手机哈哈哈，手机砸脸好痛', '邵慧留', '2026-09-30 23:12:32'),
('2026-09-30', '23:13:15', false, '肖弋洋一般单手打字还是双手', '邵慧留', '2026-09-30 23:13:15'),
('2026-09-30', '23:13:30', true, '双手', '冬.暖凉', '2026-09-30 23:13:30'),
('2026-09-30', '23:13:41', false, '＋1', '邵慧留', '2026-09-30 23:13:41'),
('2026-09-30', '23:13:46', true, '哈哈', '冬.暖凉', '2026-09-30 23:13:46'),
('2026-09-30', '23:13:50', true, '单手太慢了是吧', '冬.暖凉', '2026-09-30 23:13:50'),
