('2026-09-30', '23:13:52', false, '哈哈哈', '邵慧留', '2026-09-30 23:13:52'),
('2026-09-30', '23:13:59', false, '哈哈哈', '邵慧留', '2026-09-30 23:13:59'),
('2026-09-30', '23:14:03', true, '不是的，我是觉得单手实在是太慢了', '冬.暖凉', '2026-09-30 23:14:03'),
('2026-09-30', '23:14:08', true, '而且还得购来购去', '冬.暖凉', '2026-09-30 23:14:08'),
('2026-09-30', '23:14:31', false, '你速度比我快多了，而且你还用双拼，我都得语音转文字才跟得上你', '邵慧留', '2026-09-30 23:14:31'),
('2026-09-30', '23:14:39', false, '[Doge]', '邵慧留', '2026-09-30 23:14:39'),
('2026-09-30', '23:14:58', true, '你不觉得我是语音转文字嘛？', '冬.暖凉', '2026-09-30 23:14:58'),
('2026-09-30', '23:15:10', false, '真的假的，那我俩都是', '邵慧留', '2026-09-30 23:15:10'),
('2026-09-30', '23:15:12', false, '哈哈哈', '邵慧留', '2026-09-30 23:15:12'),
('2026-09-30', '23:15:14', true, '就算双拼的话也不会打的那么快叭', '冬.暖凉', '2026-09-30 23:15:14'),
('2026-09-30', '23:15:32', true, 'hhhhh', '冬.暖凉', '2026-09-30 23:15:32'),
('2026-09-30', '23:15:32', false, '好神奇呀，那其实我们俩还是在对话，只是通过文字的形式呈现出来而已', '邵慧留', '2026-09-30 23:15:32'),
('2026-09-30', '23:15:38', true, '的确很快', '冬.暖凉', '2026-09-30 23:15:38'),
('2026-09-30', '23:15:46', true, '嘿嘿', '冬.暖凉', '2026-09-30 23:15:46'),
('2026-09-30', '23:16:06', false, '跟你聊天咋这么开心', '邵慧留', '2026-09-30 23:16:06'),
('2026-09-30', '23:16:13', false, '我真的，一直在笑', '邵慧留', '2026-09-30 23:16:13'),
('2026-09-30', '23:16:22', true, '那看来是我的荣幸了', '冬.暖凉', '2026-09-30 23:16:22'),
