('2026-10-01', '15:48:50', false, '我好想你', '邵慧留', '2026-10-01 15:48:50'),
('2026-10-01', '15:49:00', true, '我好想你', '冬.暖凉', '2026-10-01 15:49:00'),
('2026-10-01', '15:49:14', false, '确实好看哈哈', '邵慧留', '2026-10-01 15:49:14'),
('2026-10-01', '15:49:59', false, '其实我之前想说挑战一下咱俩到底多久不联系，但是好像忍不住一点哈哈', '邵慧留', '2026-10-01 15:49:59'),
('2026-10-01', '15:50:18', true, '捂捂，我也忍不住了', '冬.暖凉', '2026-10-01 15:50:18'),
